-- ============================================================================
-- Student dashboard tables: curfew scores, monthly outing rollups
-- Generated by scripts/student-dash.mjs
-- ============================================================================
BEGIN;

-- 1. Curfew scores (per student per day)
CREATE TABLE IF NOT EXISTS public.student_curfew_scores (
  id                UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  student_user_id   UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  score_date        DATE NOT NULL,
  score             INTEGER NOT NULL DEFAULT 100 CHECK (score BETWEEN 0 AND 100),
  on_time_returns   INTEGER NOT NULL DEFAULT 0,
  late_returns      INTEGER NOT NULL DEFAULT 0,
  violations        INTEGER NOT NULL DEFAULT 0,
  created_at        TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at        TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  UNIQUE (student_user_id, score_date)
);
CREATE INDEX IF NOT EXISTS idx_curfew_scores_student_date
  ON public.student_curfew_scores (student_user_id, score_date DESC);

-- 2. Monthly outing summary (per student per YYYY-MM)
CREATE TABLE IF NOT EXISTS public.student_monthly_outing_summary (
  id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  student_user_id     UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  year_month          TEXT NOT NULL,
  total_outings       INTEGER NOT NULL DEFAULT 0,
  daily_outings       INTEGER NOT NULL DEFAULT 0,
  home_outings        INTEGER NOT NULL DEFAULT 0,
  day_passes          INTEGER NOT NULL DEFAULT 0,
  night_outings       INTEGER NOT NULL DEFAULT 0,
  total_minutes_out   INTEGER NOT NULL DEFAULT 0,
  updated_at          TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  UNIQUE (student_user_id, year_month)
);
CREATE INDEX IF NOT EXISTS idx_monthly_outing_student_month
  ON public.student_monthly_outing_summary (student_user_id, year_month DESC);

-- 3. RLS
ALTER TABLE public.student_curfew_scores          ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.student_monthly_outing_summary ENABLE ROW LEVEL SECURITY;

DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename='student_curfew_scores' AND policyname='svc_all_curfew_scores') THEN
    CREATE POLICY svc_all_curfew_scores ON public.student_curfew_scores
      FOR ALL TO service_role USING (true) WITH CHECK (true);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename='student_monthly_outing_summary' AND policyname='svc_all_monthly_outing') THEN
    CREATE POLICY svc_all_monthly_outing ON public.student_monthly_outing_summary
      FOR ALL TO service_role USING (true) WITH CHECK (true);
  END IF;
END $$;

-- 4. Rollup: curfew score
CREATE OR REPLACE FUNCTION public.recompute_curfew_score(
  p_user_id UUID,
  p_date    DATE DEFAULT (CURRENT_DATE)
) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_curfew         TEXT;
  v_curfew_minutes INTEGER;
  v_on_time        INTEGER := 0;
  v_late           INTEGER := 0;
  v_score          INTEGER;
BEGIN
  SELECT COALESCE(hostel_curfew_time, '21:00') INTO v_curfew
    FROM student_details WHERE user_id = p_user_id;
  v_curfew := COALESCE(v_curfew, '21:00');
  v_curfew_minutes :=
    CAST(split_part(v_curfew, ':', 1) AS INTEGER) * 60 +
    CAST(split_part(v_curfew, ':', 2) AS INTEGER);

  SELECT
    COUNT(*) FILTER (WHERE (EXTRACT(HOUR FROM m.timestamp AT TIME ZONE 'Asia/Kolkata') * 60 +
                            EXTRACT(MINUTE FROM m.timestamp AT TIME ZONE 'Asia/Kolkata')) <= v_curfew_minutes),
    COUNT(*) FILTER (WHERE (EXTRACT(HOUR FROM m.timestamp AT TIME ZONE 'Asia/Kolkata') * 60 +
                            EXTRACT(MINUTE FROM m.timestamp AT TIME ZONE 'Asia/Kolkata')) > v_curfew_minutes)
    INTO v_on_time, v_late
    FROM movement_logs m
   WHERE m.user_id = p_user_id AND m.direction = 'IN'
     AND (m.timestamp AT TIME ZONE 'Asia/Kolkata')::date = p_date;

  v_score := GREATEST(0, LEAST(100, 100 - (v_late * 10)));

  INSERT INTO student_curfew_scores
    (student_user_id, score_date, score, on_time_returns, late_returns, violations)
  VALUES (p_user_id, p_date, v_score, v_on_time, v_late, v_late)
  ON CONFLICT (student_user_id, score_date) DO UPDATE
    SET score           = EXCLUDED.score,
        on_time_returns = EXCLUDED.on_time_returns,
        late_returns    = EXCLUDED.late_returns,
        violations      = EXCLUDED.violations,
        updated_at      = NOW();
END;
$$;

-- 5. Rollup: monthly outing summary
CREATE OR REPLACE FUNCTION public.recompute_monthly_outing(
  p_user_id UUID,
  p_month   TEXT DEFAULT to_char(NOW() AT TIME ZONE 'Asia/Kolkata', 'YYYY-MM')
) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_total INTEGER := 0; v_daily INTEGER := 0; v_home INTEGER := 0;
  v_daypass INTEGER := 0; v_night INTEGER := 0; v_minutes INTEGER := 0;
BEGIN
  WITH outs AS (
    SELECT m.*,
      CASE
        WHEN m.reason IN ('daily_outing','Daily Outing','Outing','Day Out') THEN 'daily'
        WHEN m.reason IN ('home_out','Home Out','Home In','Weekend Outing') THEN 'home'
        WHEN m.reason IN ('day_pass','Day Pass') THEN 'daypass'
        ELSE 'other'
      END AS kind,
      EXTRACT(HOUR FROM m.timestamp AT TIME ZONE 'Asia/Kolkata') AS hh
    FROM movement_logs m
   WHERE m.user_id = p_user_id AND m.direction = 'OUT'
     AND to_char(m.timestamp AT TIME ZONE 'Asia/Kolkata', 'YYYY-MM') = p_month
  )
  SELECT COUNT(*),
         COUNT(*) FILTER (WHERE kind = 'daily'),
         COUNT(*) FILTER (WHERE kind = 'home'),
         COUNT(*) FILTER (WHERE kind = 'daypass'),
         COUNT(*) FILTER (WHERE hh >= 18 OR hh < 6)
    INTO v_total, v_daily, v_home, v_daypass, v_night FROM outs;

  SELECT COALESCE(SUM(EXTRACT(EPOCH FROM (next_in - out_ts)) / 60), 0)
    INTO v_minutes
    FROM (
      SELECT m.timestamp AS out_ts, m.direction,
             LEAD(m.timestamp) OVER (PARTITION BY m.user_id ORDER BY m.timestamp) AS next_in
        FROM movement_logs m
       WHERE m.user_id = p_user_id
         AND to_char(m.timestamp AT TIME ZONE 'Asia/Kolkata', 'YYYY-MM') = p_month
    ) pair
   WHERE direction = 'OUT' AND next_in IS NOT NULL;

  INSERT INTO student_monthly_outing_summary
    (student_user_id, year_month, total_outings, daily_outings, home_outings,
     day_passes, night_outings, total_minutes_out)
  VALUES (p_user_id, p_month, v_total, v_daily, v_home, v_daypass, v_night, v_minutes::INT)
  ON CONFLICT (student_user_id, year_month) DO UPDATE
    SET total_outings     = EXCLUDED.total_outings,
        daily_outings     = EXCLUDED.daily_outings,
        home_outings      = EXCLUDED.home_outings,
        day_passes        = EXCLUDED.day_passes,
        night_outings     = EXCLUDED.night_outings,
        total_minutes_out = EXCLUDED.total_minutes_out,
        updated_at        = NOW();
END;
$$;

-- 6. Trigger
CREATE OR REPLACE FUNCTION public.trg_movement_recompute_student_rollups()
RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  IF EXISTS (SELECT 1 FROM users WHERE id = NEW.user_id AND role = 'student') THEN
    PERFORM recompute_curfew_score(NEW.user_id, (NEW.timestamp AT TIME ZONE 'Asia/Kolkata')::date);
    PERFORM recompute_monthly_outing(NEW.user_id, to_char(NEW.timestamp AT TIME ZONE 'Asia/Kolkata', 'YYYY-MM'));
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_movement_recompute_student ON public.movement_logs;
CREATE TRIGGER trg_movement_recompute_student
  AFTER INSERT ON public.movement_logs
  FOR EACH ROW EXECUTE FUNCTION public.trg_movement_recompute_student_rollups();

COMMIT;
